$ErrorActionPreference = "Stop"

$root = $PSScriptRoot
$backup = Join-Path $HOME ("Downloads\hosted-card-vault-backup-" + (Get-Date -Format "yyyyMMdd-HHmmss"))
New-Item -ItemType Directory -Path $backup -Force | Out-Null

function Write-ReplacementFile {
  param(
    [Parameter(Mandatory = $true)]
    [string]$RelativePath,

    [Parameter(Mandatory = $true)]
    [string]$CompressedBase64
  )

  $target = Join-Path $root $RelativePath
  $backupTarget = Join-Path $backup $RelativePath

  if (Test-Path $target) {
    New-Item -ItemType Directory -Path (Split-Path $backupTarget) -Force | Out-Null
    Copy-Item $target $backupTarget -Force
  }

  New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null

  $bytes = [Convert]::FromBase64String($CompressedBase64)
  $inputStream = New-Object IO.MemoryStream(,$bytes)
  $gzipStream = New-Object IO.Compression.GzipStream(
    $inputStream,
    [IO.Compression.CompressionMode]::Decompress
  )
  $reader = New-Object IO.StreamReader($gzipStream)
  $content = $reader.ReadToEnd()

  $reader.Dispose()
  $gzipStream.Dispose()
  $inputStream.Dispose()

  [IO.File]::WriteAllText(
    $target,
    $content,
    (New-Object Text.UTF8Encoding($false))
  )

  Write-Host "Updated $RelativePath"
}

Write-ReplacementFile -RelativePath "app\api\paypal\client-token\route.ts" -CompressedBase64 ""
Write-ReplacementFile -RelativePath "app\api\business-advertising\payment\route.ts" -CompressedBase64 ""
Write-ReplacementFile -RelativePath "app\business-advertising\payment\page.tsx" -CompressedBase64 ""

Write-Host ""
Write-Host "PayPal hosted debit and credit card vault checkout installed."
Write-Host ""
Write-Host "This update adds:"
Write-Host "- PayPal-generated short-lived card client tokens"
Write-Host "- PayPal-hosted name, card number, expiry, and CVV fields"
Write-Host "- 3D Secure when required"
Write-Host "- Card vaulting after successful payment"
Write-Host "- Automatic future approved-campaign charging through the existing saved-token system"
Write-Host "- Safe fallback to PayPal Wallet if card fields are unavailable"
Write-Host ""
Write-Host "No full card number or CVV is sent to or stored by the SOLO BEATS server."
Write-Host ""
Write-Host "Backup saved outside the project at:"
Write-Host $backup
Write-Host ""
Write-Host "Next command: npm run build"
